pub struct Tokenizer<'a> {
    remainder: &'a str,
    delimiter: char,
}

impl<'a> Tokenizer<'a> {
    pub fn new(input: &'a str, delimiter: char) -> Self {
        Self { remainder: input, delimiter }
    }
}

impl<'a> Iterator for Tokenizer<'a> {
    type Item = &'a str;
    fn next(&mut self) -> Option<Self::Item> {
        if self.remainder.is_empty() {
            return None;
        }
        match self.remainder.find(self.delimiter) {
            Some(idx) => {
                let token = &self.remainder[..idx];
                self.remainder = &self.remainder[idx + self.delimiter.len_utf8()..];
                Some(token)
            }
            None => {
                let token = self.remainder;
                self.remainder = "";
                Some(token)
            }
        }
    }
}

